package com.example.rokidgeminisecretary;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** One conversation-side media entry, with image/video badges rather than separate generation modes. */
final class GeneratedImagePanel {
 private final Activity host;private final LinearLayout root;private final Button open;private final TextView status;private final ImageView preview;private Bitmap bitmap;private String signature="";final GeneratedVideoPanel videoPanel;
 GeneratedImagePanel(Activity host){this.host=host;videoPanel=new GeneratedVideoPanel(host);root=new LinearLayout(host);root.setOrientation(1);open=new Button(host);open.setText("生成した画像・動画");open.setOnClickListener(v->list());root.addView(open);status=new TextView(host);status.setTextSize(12);status.setMaxLines(3);status.setEllipsize(android.text.TextUtils.TruncateAt.END);root.addView(status);preview=new ImageView(host);preview.setScaleType(ImageView.ScaleType.FIT_CENTER);preview.setContentDescription("直近の生成画像");root.addView(preview,new LinearLayout.LayoutParams(-1,Math.round(100*host.getResources().getDisplayMetrics().density)));preview.setVisibility(View.GONE);refresh();}
 View view(){return root;}
 void close(){preview.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}videoPanel.close();}
 static JSONArray all(Context c)throws Exception{ArrayList<JSONObject> items=new ArrayList<>();for(String kind:new String[]{"IMAGE","VIDEO"}){JSONArray list=kind.equals("IMAGE")?ImageGeneration.list(c):VideoGeneration.list(c);for(int i=0;i<list.length();i++)items.add(new JSONObject(list.getJSONObject(i).toString()).put("mediaKind",kind));}items.sort((a,b)->Long.compare(b.optLong("time"),a.optLong("time")));JSONArray result=new JSONArray();for(JSONObject j:items)result.put(j);return result;}
 void refresh(){try{JSONArray jobs=all(host);String next=jobs.toString();if(next.equals(signature))return;signature=next;preview.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}preview.setVisibility(View.GONE);if(jobs.length()==0){status.setText("会話から画像や動画を依頼できます。指示と元画像をGeminiへ送ります。生成にはAPI利用料がかかります。");return;}JSONObject j=jobs.getJSONObject(0);boolean video=j.optString("mediaKind").equals("VIDEO");status.setText((video?GeneratedVideoPanel.label(j):"画像 · "+label(j))+" · "+j.optString("prompt"));if(!video&&"completed".equals(j.optString("state"))){byte[] b=ImageGeneration.image(host,j.getString("id"),true);bitmap=BitmapFactory.decodeByteArray(b,0,b.length);preview.setImageBitmap(bitmap);preview.setVisibility(View.VISIBLE);String id=j.getString("id");preview.setOnClickListener(v->show(id));}}catch(Exception e){status.setText("生成した画像・動画の状態を取得できません");}}
 static String label(JSONObject j){switch(j.optString("state")){case "queued":return "受付済み";case "running":return "生成中…";case "completed":return (j.has("galleryError")||!j.has("galleryUri"))?"完成・ギャラリー保存を再試行してください":"完成・ギャラリー保存済み";default:return "生成失敗："+j.optString("error","状態を確認してください");}}
 void prompt(String parent){EditText input=new EditText(host);input.setHint(parent.isEmpty()?"例：ロキを描いて／ロキが踊る動画を作って":"例：背景を夕焼けにして／手を振る動画にして");input.setMinLines(2);new AlertDialog.Builder(host).setTitle(parent.isEmpty()?"画像・動画を頼む":"この画像から続けて頼む").setMessage("文面と直前の生成内容から画像・動画を判断します。指示・元画像をGeminiへ送信し、API利用料がかかります。").setView(input).setNegativeButton("取消",null).setPositiveButton("送信",(d,w)->{try{String text=input.getText().toString();MediaGenerationIntent.Kind kind=MediaGenerationContext.kind(host,text,!parent.isEmpty());if(kind==MediaGenerationIntent.Kind.VIDEO)VideoGeneration.enqueue(host,UUID.randomUUID().toString(),text,null,parent);else if(kind==MediaGenerationIntent.Kind.IMAGE)ImageGeneration.enqueue(host,UUID.randomUUID().toString(),text,null,parent);else throw new java.io.IOException("作りたい画像や動きを入力してください。普通の会話は会話欄から送れます。");refresh();}catch(Exception e){Toast.makeText(host,e.getMessage(),Toast.LENGTH_LONG).show();}}).show();}
 void list(){try{JSONArray jobs=all(host);String[] labels=new String[jobs.length()];for(int i=0;i<labels.length;i++){JSONObject j=jobs.getJSONObject(i);boolean video=j.optString("mediaKind").equals("VIDEO");labels[i]=(video?"動画 · "+GeneratedVideoPanel.label(j):"画像 · "+label(j))+"\n"+j.optString("prompt");}new AlertDialog.Builder(host).setTitle("生成した画像・動画（新しい順）").setItems(labels,(d,i)->{try{JSONObject j=jobs.getJSONObject(i);if(j.optString("mediaKind").equals("VIDEO"))videoPanel.show(j);else if("completed".equals(j.optString("state")))show(j.getString("id"));else new AlertDialog.Builder(host).setMessage(label(j)).setPositiveButton("閉じる",null).setNeutralButton("ロキ内の記録を削除",(x,w)->remove(j.optString("id"))).show();}catch(Exception e){Toast.makeText(host,e.getMessage(),1).show();}}).setPositiveButton("続けて頼む",(d,w)->prompt("")).setNegativeButton("閉じる",null).show();}catch(Exception e){status.setText("一覧を取得できません");}}
 void show(String id){try{byte[] bytes=ImageGeneration.image(host,id,false);BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>1024)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);ImageView image=new ImageView(host);image.setImageBitmap(b);image.setContentDescription("生成画像。長押しでロキ内から削除");image.setAdjustViewBounds(true);image.setScaleType(ImageView.ScaleType.FIT_CENTER);ScrollView scroll=new ScrollView(host);scroll.addView(image);AlertDialog dialog=new AlertDialog.Builder(host).setTitle("生成画像").setView(scroll).setPositiveButton("この画像から続ける",(d,w)->prompt(id)).setNeutralButton("ギャラリーに保存",(d,w)->new Thread(()->{try{ImageGeneration.gallery(host,id);host.runOnUiThread(()->Toast.makeText(host,"保存を確認しました",0).show());}catch(Exception e){host.runOnUiThread(()->Toast.makeText(host,"ギャラリー保存に失敗しました",1).show());}},"GeneratedGallerySave").start()).setNegativeButton("閉じる",null).create();dialog.setOnDismissListener(d->{image.setImageDrawable(null);if(b!=null)b.recycle();});dialog.show();image.setOnLongClickListener(v->{remove(id);return true;});}catch(Exception e){Toast.makeText(host,"画像を開けません",1).show();}}
 void remove(String id){new AlertDialog.Builder(host).setMessage("ロキ内の生成画像・指示を削除します。ギャラリーに保存済みのコピーは残ります。").setPositiveButton("削除",(d,w)->{try{ImageGeneration.delete(host,id);signature="";refresh();}catch(Exception e){Toast.makeText(host,e.getMessage(),1).show();}}).setNegativeButton("取消",null).show();}
}
